/* Local preparation tools. Uses the host's guarded v1 save/restore pipeline. */
(function(){'use strict';
const D=window.L4_PREP_DATA, routes=['prep','mock','mistakes','sql','compare','speak','materials','terms'];
const names={prep:'Preparation studio',mock:'Mock EPA',mistakes:'Mistake notebook',sql:'SQL challenges',compare:'Visual comparisons',speak:'Spoken answers',materials:'Course materials',terms:'Terminology'};
const checkNames=['What I did / explained','Why I chose it','How I checked it','Result and evidence reference'];
const blank=()=>({activeMock:null,mocks:{},mistakes:{},resources:{},sql:{},comparisons:{},recordings:{},mistakeDraft:null,resourceDraft:null,deleted:[]});
function validate(raw,ids){
 if(raw===undefined)return blank();
 const fail=()=>{throw new Error('Invalid preparation record. Check IDs, text limits, dates and saved selections.');};
 const obj=x=>{if(!x||typeof x!=='object'||Array.isArray(x))fail();return x;};
 const str=(x,max=10000)=>{if(typeof x!=='string'||x.length>max)fail();return x;};
 const num=(x,min,max)=>{if(!Number.isInteger(x)||x<min||x>max)fail();return x;};
 const arr=(x,max)=>{if(!Array.isArray(x)||x.length>max)fail();return x;};
 const unique=x=>{if(new Set(x).size!==x.length)fail();return x;};
 const id=x=>{if(['__proto__','constructor','prototype'].includes(x)||!/^[a-zA-Z0-9_-]{1,100}$/.test(str(x,100)))fail();return x;};
 const ksb=x=>{if(!ids.includes(x))fail();return x;};
 const date=x=>{str(x,10);if(x&&(!/^\d{4}-\d{2}-\d{2}$/.test(x)||new Date(x+'T12:00:00Z').toISOString().slice(0,10)!==x))fail();return x;};
 const checks=x=>arr(x,4).length===4?x.map(b=>{if(typeof b!=='boolean')fail();return b;}):fail();
 const exact=(x,keys)=>{obj(x);if(Object.keys(x).some(k=>!keys.includes(k)))fail();};
 const draft=(x,kind)=>{obj(x);const common={id:id(x.id)};if(kind==='resource'){exact(x,['id','title','url','notes','ksbs']);common.title=str(x.title,200);common.url=str(x.url,2000);common.notes=str(x.notes);common.ksbs=unique(arr(x.ksbs,37).map(ksb));}else{exact(x,['id','ksb','source','thought','why','remember','nextReview','variant','response','reviewedDate']);common.ksb=ksb(x.ksb);common.source=str(x.source,1000);for(const f of ['thought','why','remember','response'])common[f]=str(x[f]);common.nextReview=date(x.nextReview);common.reviewedDate=date(x.reviewedDate);common.variant=num(x.variant,0,1);}return common;};
 const mock=x=>{exact(x,['id','date','started','minutes','index','queue','answers','finished']);const y={id:id(x.id),date:date(x.date),started:num(x.started,0,8640000000000000),minutes:num(x.minutes,10,20),queue:unique(arr(x.queue,6).map(ksb)),finished:date(x.finished)};if(![3,6].includes(y.queue.length)||![10,20].includes(y.minutes)||!y.date||new Set(y.queue.map(k=>k[0])).size!==3)fail();y.index=num(x.index,0,y.queue.length-1);y.answers=arr(x.answers,6).map(a=>{exact(a,['response','checks','next']);return {response:str(a.response),checks:checks(a.checks),next:str(a.next,2000)};});if(y.answers.length!==y.queue.length)fail();return y;};
 const out=blank();exact(raw,Object.keys(out));
 for(const kind of ['mocks','mistakes','resources','sql','comparisons','recordings']){obj(raw[kind]);if(Object.keys(raw[kind]).length>500)fail();for(const [key,value] of Object.entries(raw[kind])){id(key);let record;
 if(kind==='mocks'){record=mock(value);if(record.id!==key||!record.finished)fail();}
 if(kind==='mistakes'||kind==='resources'){record=draft(value,kind==='resources'?'resource':'mistake');if(record.id!==key)fail();if(kind==='resources'&&record.url&&!safeUrl(record.url))fail();if(kind==='resources'&&(!record.title.trim()||!record.ksbs.length||(!record.url&&!record.notes.trim())))fail();if(kind==='mistakes'&&(!record.thought.trim()||!record.why.trim()||!record.remember.trim()))fail();}
 if(kind==='sql'){if(!D.sql.some(s=>s.id===key))fail();exact(value,['query','hint','runs']);record={query:str(value.query,8000),hint:num(value.hint,0,3),runs:num(value.runs,0,1000000)};}
 if(kind==='comparisons'){const c=D.comparisons.find(c=>c.id===key);if(!c)fail();exact(value,['variant','choice','reason','revealed']);record={variant:num(value.variant,0,1),choice:value.choice===null?null:num(value.choice,0,1),reason:str(value.reason,2000),revealed:value.revealed};if(typeof record.revealed!=='boolean'||record.revealed&&(record.choice===null||!record.reason.trim()))fail();}
 if(kind==='recordings'){exact(value,['id','ksb','date','duration','mime','checks','note']);record={id:id(value.id),ksb:ksb(value.ksb),date:date(value.date),duration:num(value.duration,1,121),mime:str(value.mime,100),checks:checks(value.checks),note:str(value.note,2000)};if(record.id!==key||!record.date||!/^audio\/(webm|ogg|mp4)(;codecs=[a-zA-Z0-9.,-]+)?$/.test(record.mime))fail();}
 out[kind][key]=record;
 }}
 if(raw.activeMock!==null){out.activeMock=mock(raw.activeMock);if(out.activeMock.finished)fail();}
 if(raw.mistakeDraft!==null)out.mistakeDraft=draft(raw.mistakeDraft,'mistake');
 if(raw.resourceDraft!==null)out.resourceDraft=draft(raw.resourceDraft,'resource');
 out.deleted=unique(arr(raw.deleted,3000).map(x=>{str(x,120);if(!/^(mocks|mistakes|resources|recordings):[a-zA-Z0-9_-]{1,100}$/.test(x))fail();return x;}));
 for(const token of out.deleted){const [kind,key]=token.split(':');delete out[kind][key];if(kind==='resources'&&out.resourceDraft?.id===key)out.resourceDraft=null;if(kind==='mistakes'&&out.mistakeDraft?.id===key)out.mistakeDraft=null;}
 return out;
}
function merge(current,incoming,choices){const merged=structuredClone(current),conflicts=[];const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
 for(const field of ['activeMock','mistakeDraft','resourceDraft']){if(incoming[field]===null||same(current[field],incoming[field]))continue;const key='prep-'+field;if(current[field]!==null){conflicts.push({key,label:'Preparation: '+field});if(choices[key]!=='import')continue;}merged[field]=structuredClone(incoming[field]);}
 for(const kind of ['mocks','mistakes','resources','sql','comparisons','recordings'])for(const [id,r] of Object.entries(incoming[kind])){if(same(merged[kind][id],r))continue;const key='prep-'+kind+'-'+id;if(Object.hasOwn(merged[kind],id)){conflicts.push({key,label:'Preparation · '+kind+': '+id});if(choices[key]!=='import')continue;}merged[kind][id]=structuredClone(r);}
 merged.deleted=[...new Set([...current.deleted,...incoming.deleted])];for(const token of merged.deleted){const [kind,id]=token.split(':');delete merged[kind][id];if(kind==='resources'&&merged.resourceDraft?.id===id)merged.resourceDraft=null;if(kind==='mistakes'&&merged.mistakeDraft?.id===id)merged.mistakeDraft=null;}return {merged,conflicts};
}
function safeUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
let A,ui={sql:'filter',comparison:'identity',mock:'',materialFilter:'',mistakeFilter:'',termSearch:'',speakKsb:'K8',limit:120},sqlResult=null,sqlWorker=null,sqlTimer=null,audioToken=0,audio=null,audioMessage='',audioURLs=[],memoryAudio=new Map(),dbPromise=null;
const state=()=>A.state().preparation,E=x=>A.esc(x),ksbLinks=ids=>ids.map(id=>`<a href="#ksb-${id.toLowerCase()}">${E(id)}</a>`).join(' · ');
const button=(label,action,extra='',secondary=false)=>`<button type="button" class="button ${secondary?'secondary ':''}small" data-prep="${action}" ${extra}>${label}</button>`;
const textarea=(label,id,value,extra='')=>`<label class="prep-field" for="${id}">${label}</label><textarea id="${id}" ${extra.includes('rows=')?'':'rows="4"'} ${extra.includes('maxlength=')?'':'maxlength="10000"'} ${extra}>${E(value)}</textarea>`;
const input=(label,id,value,type='text',extra='')=>`<label class="prep-field" for="${id}">${label}</label><input id="${id}" type="${type}" value="${E(value)}" ${extra}>`;
const options=(values,selected)=>Object.entries(values).map(([v,label])=>`<option value="${E(v)}"${String(selected)===v?' selected':''}>${E(label)}</option>`).join('');
const select=(label,id,values,selected,extra='')=>`<div class="prep-select"><label class="prep-field" for="${id}">${label}</label><select id="${id}" ${extra}>${options(values,selected)}</select></div>`;
const ksbs=()=>Object.fromEntries(A.items.map(k=>[k.id,k.id+' · '+k.title]));
const emptyChecks=()=>[false,false,false,false];
function room(kind,id=''){if(Object.keys(state()[kind]).length>=500&&!Object.hasOwn(state()[kind],id)){A.toast('This collection has reached 500 records. Export a backup, then remove an older record before adding another.');return false;}return true;}
function persist(){A.save();}
function redraw(){A.render();}
function shell(view,title,description,body){return `<div class="prep-shell"><a class="back-link" href="#practice">‹ Back to Practice</a><header class="page-header"><p class="eyebrow">Preparation studio</p><h1>${title}</h1><p>${description}</p></header><nav class="prep-nav" aria-label="Preparation tools">${select('Preparation tool','prep-route',names,view)}${routes.map(r=>`<a href="#${r}"${view===r?' aria-current="page"':''}>${names[r]}</a>`).join('')}</nav>${body}</div>`;}
function card(h,p,route,cta){return `<article class="prep-card"><h2>${h}</h2><p>${p}</p><a class="button secondary small" href="#${route}">${cta}</a></article>`;}
function studio(){const s=state(),due=Object.values(s.mistakes).filter(m=>m.nextReview&&m.nextReview<=A.today()).length;return shell('prep','Practise it. Explain it. Remember it.','A place to rehearse the assessment, test a query and turn mistakes into useful reminders.',`<div class="prep-banner"><strong>${s.activeMock?'Your mock session is ready to resume.':'Choose one small task for today.'}</strong><p>${due?`${due} notebook reminder${due===1?' is':'s are'} due.`:'Try one SQL challenge, a visual comparison or a spoken explanation.'}</p><div class="button-row"><a class="button" href="#${s.activeMock?'mock':due?'mistakes':'sql'}">${s.activeMock?'Resume mock EPA':due?'Revisit a mistake':'Write a SQL query'}</a><a class="button secondary" href="#speak">Practise out loud</a></div></div><p class="note"><a href="#assessment-practice">Use provider sample questions and evaluation exercises</a> · <a href="#evidence-packs">Plan provider evidence packs</a></p><div class="prep-grid">${card('Mock EPA','A mixed Knowledge, Skill and Behaviour rehearsal. Review guidance after completing the set.','mock','Start or resume')}${card('Mistake notebook','Record the misunderstanding, its correction and a reminder. Return to it through a different question.','mistakes','Open notebook')}${card('SQL challenges','Run real SQLite queries on six synthetic requests. Compare actual output with the expected result.','sql','Open SQL desk')}${card('Visual comparisons','Six side-by-side memory cards, each with two application questions.','compare','Compare concepts')}${card('Spoken answers','Record up to two minutes, listen back and check the structure of your answer.','speak','Open recording desk')}${card('Course materials','Save a link or paste a note, then connect it to the KSBs it supports.','materials','Add a resource')}${card('Terminology','Quick definitions, visual examples and common mistakes. Dotted terms in lessons open the same help.','terms','Explore terms')}</div><p class="small muted">These tools record practice. Your recall, personal examples, evidence and existing quest rewards remain independently recorded.</p>`);}
function mock(){const s=state(),m=s.activeMock,finished=s.mocks[ui.mock]||Object.values(s.mocks).at(-1);let content='';
 if(m){const id=m.queue[m.index],a=m.answers[m.index],k=A.byId(id);content=`<section class="panel"><div class="session-strip"><strong>Question ${m.index+1} of ${m.queue.length} · ${E(id)}</strong><span id="prep-mock-time" class="small"></span></div><p class="small">Suggested duration ${m.minutes} minutes. The clock is advisory; your answers stay editable. Guidance appears after the whole set.</p><h2>${E(m.index<3?k.question:k.probe)}</h2>${textarea('Your answer — include your own actions, reasons, checks and result','prep-mock-response',a.response)}<div class="button-row">${button('Previous question','mock-prev','',true).replace('data-prep="mock-prev"',`data-prep="mock-prev"${m.index===0?' disabled':''}`)}${button(m.index===m.queue.length-1?'Finish and review the set':'Save and next question','mock-next')}<a class="button secondary small" href="#prep">Save and pause</a></div><p class="small muted">Use approved evidence references, not sensitive source records. This independent mock does not replace your usual practice session.</p></section>`;}
 else content=`<section class="panel"><h2>Rehearse without answer hints</h2><p>Choose a short mixed set. Each contains Knowledge, Skill and Behaviour questions. Answers save as you type; you can pause and resume.</p><div class="two-fields">${select('Question set','prep-mock-count',{3:'3 questions · about 10 minutes',6:'6 questions · about 20 minutes'},3)}</div>${button('Begin mock EPA','mock-start')}</section>${finished?mockReview(finished):''}`;
 const history=Object.values(s.mocks).reverse();if(history.length)content+=`<details class="content-section"><summary>Completed mocks (${history.length})</summary>${history.map(m=>`<p>${E(m.date)} · ${m.queue.length} questions ${button('Review','mock-open',`data-id="${m.id}"`,true)} ${button('Delete','remove',`data-kind="mocks" data-id="${m.id}"`,true)}</p>`).join('')}</details>`;
 return shell('mock','Your mock EPA rehearsal','Practise explaining decisions and evidence across KSBs. This is a preparation exercise, not an official assessment or an automatic grade.',content);}
function mockReview(m){return `<section class="prep-review" data-mock-review><h2>Review the whole conversation</h2><p>${E(m.finished)} · ${m.queue.length} questions. Read your own answer first, then compare it with the guidance. Tick only what your answer actually covers.</p>${m.queue.map((id,i)=>{const a=m.answers[i],k=A.byId(id);return `<article class="panel"><h3>${E(id)} · ${E(i<3?k.question:k.probe)}</h3><p class="prep-user-text">${E(a.response||'No answer recorded.')}</p><fieldset class="prep-checks"><legend>My self-review</legend>${checkNames.map((label,n)=>`<label><input type="checkbox" data-mock-check="${m.id}" data-index="${i}" data-check="${n}"${a.checks[n]?' checked':''}>${label}</label>`).join('')}</fieldset>${textarea('One thing to strengthen','prep-mock-next-'+i,a.next,`data-mock-next="${m.id}" data-index="${i}" maxlength="2000"`)}<details><summary>Compare with the ${id} guide</summary><div class="prose">${k.quick}</div><ul>${k.targets.map(t=>`<li>${E(t)}</li>`).join('')}</ul><p><a href="#ksb-${id.toLowerCase()}">Read the complete ${id} lesson</a></p></details></article>`;}).join('')}${button('Download this review','mock-export',`data-id="${m.id}"`,true)}</section>`;}
function newMistake(ksb='K8',source='',thought=''){return {id:A.uid(),ksb,source,thought,why:'',remember:'',nextReview:A.addDays(1),variant:0,response:'',reviewedDate:''};}
function mistakes(){const s=state(),d=s.mistakeDraft,records=Object.values(s.mistakes).filter(m=>!ui.mistakeFilter||m.ksb===ui.mistakeFilter).sort((a,b)=>(a.nextReview||'9999').localeCompare(b.nextReview||'9999'));
 return shell('mistakes','Make the mistake useful.','Keep a short correction in your own words, then revisit the idea through a new question.',`${d?`<form id="prep-mistake-form" class="panel"><h2>${s.mistakes[d.id]?'Edit':'New'} notebook entry</h2>${select('Related KSB','prep-mistake-ksb',ksbs(),d.ksb)}${input('Question or source (optional)','prep-mistake-source',d.source,'text','maxlength="1000"')}${textarea('What I thought','prep-mistake-thought',d.thought,'required')}${textarea('Why it was wrong or incomplete','prep-mistake-why',d.why,'required')}${textarea('What I’ll remember','prep-mistake-remember',d.remember,'required')}${input('Revisit on','prep-mistake-date',d.nextReview,'date')}<div class="button-row"><button class="button small" type="submit">Save notebook entry</button>${button('Discard draft','mistake-cancel','',true)}</div></form>`:button('Add a mistake or learning point','mistake-new')}${select('Filter notebook by KSB','prep-mistake-filter',{'':'All KSBs',...ksbs()},ui.mistakeFilter)}<p class="small">${records.length} saved entries. A due date is a local reminder on this page.</p>${records.map(m=>`<article class="panel prep-mistake" data-mistake="${m.id}"><div class="section-heading"><h2>${E(m.ksb)} · ${m.nextReview&&m.nextReview<=A.today()?'Due for a revisit':'Learning point'}</h2><span class="small">${E(m.nextReview||'No review date')}</span></div>${m.source?`<p class="small">Source: ${E(m.source)}</p>`:''}<dl class="prep-correction"><dt>What I thought</dt><dd>${E(m.thought)}</dd><dt>Why it was wrong or incomplete</dt><dd>${E(m.why)}</dd><dt>What I’ll remember</dt><dd>${E(m.remember)}</dd></dl><details><summary>Apply it to a different question</summary><p>${E(m.variant?A.byId(m.ksb).probe:A.scenario(m.ksb))}</p>${textarea('My explanation in this situation','prep-revisit-'+m.id,m.response,`data-mistake-response="${m.id}"`)}<div class="button-row">${button('I explained it — revisit in 7 days','mistake-review',`data-id="${m.id}" data-days="7"`)}${button('Still unsure — revisit tomorrow','mistake-review',`data-id="${m.id}" data-days="1"`,true)}${button('Try the other prompt','mistake-variant',`data-id="${m.id}"`,true)}</div><p class="small">Self-recorded reflection; no automatic correctness or evidence award. Last revisit: ${E(m.reviewedDate||'None yet')}.</p></details><div class="button-row">${button('Edit','mistake-edit',`data-id="${m.id}"`,true)}${button('Delete','remove',`data-kind="mistakes" data-id="${m.id}"`,true)}${ksbLinks([m.ksb])}</div></article>`).join('')||'<div class="quiet-box">Your notebook is ready. You can also add an entry directly after a misconception quiz.</div>'}`);}
function resourceDraft(){return {id:A.uid(),title:'',url:'',notes:'',ksbs:ui.materialFilter?[ui.materialFilter]:[]};}
function materials(){const s=state(),d=s.resourceDraft,records=Object.values(s.resources).filter(r=>!ui.materialFilter||r.ksbs.includes(ui.materialFilter));return shell('materials','Your course-material shelf','Keep approved links or paste your own study notes. Tag each resource so it appears beside the relevant KSB lesson.',`${d?`<form id="prep-resource-form" class="panel"><h2>${s.resources[d.id]?'Edit resource':'Add a resource'}</h2>${input('Title','prep-resource-title',d.title,'text','required maxlength="200"')}${input('Web link (optional; http or https)','prep-resource-url',d.url,'url','maxlength="2000"')}${textarea('Pasted notes (optional if you add a link)','prep-resource-notes',d.notes)}<fieldset><legend>Related KSBs — choose at least one</legend><div class="prep-tag-grid">${A.items.map(k=>`<label title="${E(k.title)}"><input type="checkbox" data-resource-ksb="${k.id}"${d.ksbs.includes(k.id)?' checked':''}>${k.id}</label>`).join('')}</div></fieldset><p class="small">Notes are stored as plain text. Links open only when you select them. Keep sensitive workplace material in approved storage.</p><p id="prep-resource-error" role="alert" class="error-text"></p><div class="button-row"><button type="submit" class="button small">Save resource</button>${button('Discard draft','resource-cancel','',true)}</div></form>`:button('Add a link or note','resource-new')}${select('Filter resources by KSB','prep-resource-filter',{'':'All KSBs',...ksbs()},ui.materialFilter)}<div class="prep-grid">${records.map(r=>resourceCard(r,true)).join('')||'<p class="quiet-box">No resources match yet. Add a useful course page or a note from a session.</p>'}</div><p class="small muted">Your JSON backup includes resources and notes. External links need their own network access and permission; this page does not download their content.</p>`);}
function resourceCard(r,editing=false){return `<article class="prep-card"><h3>${E(r.title)}</h3><p class="small">${ksbLinks(r.ksbs)}</p>${r.url?`<p><a href="${E(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">Open resource ↗ <span class="small">(${E(new URL(r.url).hostname)})</span></a></p>`:''}${r.notes?`<details><summary>Read saved notes</summary><p class="prep-user-text">${E(r.notes)}</p></details>`:''}${editing?`<div class="button-row">${button('Edit','resource-edit',`data-id="${r.id}"`,true)}${button('Delete','remove',`data-kind="resources" data-id="${r.id}"`,true)}</div>`:''}</article>`;}
function lessonPanel(id){const records=Object.values(state().resources).filter(r=>r.ksbs.includes(id));return `<section class="prep-lesson"><h2>Bring your own learning to ${id}</h2><div class="button-row">${button('Record a spoken answer','speak-topic',`data-id="${id}"`,true)}${button('Add a course resource','resource-topic',`data-id="${id}"`,true)}<a class="button secondary small" href="#compare">Visual comparisons</a></div>${records.length?`<div class="prep-grid">${records.map(r=>resourceCard(r)).join('')}</div>`:'<p class="small muted">Resources tagged with this KSB will appear here.</p>'}</section>`;}
function resultTable(columns,rows){return `<div class="prep-table-wrap"><table><thead><tr>${columns.map(c=>`<th scope="col">${E(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v===null?'<span class="prep-null">NULL</span>':E(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function sql(){const c=D.sql.find(c=>c.id===ui.sql),r=state().sql[c.id]||{query:c.starter,hint:0,runs:0};return shell('sql','A small SQL desk. Real results.','Write and run SQLite SELECT queries against a fictional service-request dataset. Everything runs on this device.',`${select('Challenge','prep-sql-select',Object.fromEntries(D.sql.map(c=>[c.id,c.title])),c.id)}<section class="panel"><p class="small">${ksbLinks(c.ksbs)}</p><h2>${c.title}</h2><p>${c.task}</p><details><summary>Inspect the six requests and three services</summary><p>requests: request_id INTEGER PRIMARY KEY, service_id TEXT, days INTEGER, status TEXT.<br>services: service_id TEXT PRIMARY KEY, service TEXT. The unknown service X is intentional.</p><h3>requests</h3>${resultTable(['request_id','service_id','days','status'],[[1,'A',2,'closed'],[2,'A',8,'closed'],[3,'B',null,'open'],[4,'B',5,'closed'],[5,'X',12,'closed'],[6,'A',null,'open']])}<h3>services</h3>${resultTable(['service_id','service'],[['A','Benefits'],['B','Housing'],['C','Libraries']])}</details>${textarea('Your SQL query','prep-sql-query',r.query,'spellcheck="false" maxlength="8000" rows="7"')}<div class="button-row">${button(sqlWorker?'Running…':'Run query','sql-run',sqlWorker?'disabled':'')}${button('Next hint','sql-hint','',true)}${button('Reset this query','sql-reset','',true)}</div><p class="small muted">Read-only database. One query at a time; up to 100 result rows; 8-second time limit. Uses SQLite syntax. Saved or imported code only runs when you press Run query.</p>${r.hint?`<div class="note"><strong>Hint ${Math.min(r.hint,2)} of 2</strong><p>${E(c.hints[Math.min(r.hint,2)-1])}</p></div>`:''}${r.hint>=3?`<details open><summary>Worked query</summary><pre><code>${E(c.answer)}</code></pre><p>${E(c.why)}</p></details>`:''}<h3>Expected result</h3>${resultTable(c.columns,c.rows)}<div id="prep-sql-result" role="status" tabindex="-1">${sqlFeedback(c)}</div></section>`);}
function sqlFeedback(c){if(!sqlResult||sqlResult.id!==c.id)return '<p class="small">Run your query to see its actual result here.</p>';if(sqlResult.error)return `<div class="note warning"><h3>Query needs a change</h3><p>${E(sqlResult.error)}</p></div>`;const matched=matches(c,sqlResult);return `<div class="note ${matched?'':'warning'}"><h3>${matched?'The result matches.':'Compare your result with the expected rows.'}</h3><p>${matched?E(c.why):'Check the column names, row order, filters and join keys. NULL is different from zero or an empty string.'}</p>${resultTable(sqlResult.columns,sqlResult.rows)}<p class="small">${sqlResult.rows.length} result rows. Matching this small fixture is a useful check; explain why your query fits the requirement.</p></div>`;}
function matches(c,result){return JSON.stringify(c.columns)===JSON.stringify(result.columns)&&JSON.stringify(c.rows)===JSON.stringify(result.rows);}
// The pinned vendor source is reassembled byte-for-byte in a disposable Blob worker.
// Only trusted engine/fixture code is compiled; user queries travel as message data.
function workerMain(){self.onmessage=async event=>{let db,stmt;try{const SQL=await initSqlJs();db=new SQL.Database();db.run(event.data.setup);db.run('PRAGMA hard_heap_limit=33554432');db.run('PRAGMA query_only=ON');const iterator=db.iterateStatements(event.data.query);const first=iterator.next();if(first.done)throw new Error('Write a SELECT query first.');stmt=first.value;const columns=stmt.getColumnNames();if(!columns.length)throw new Error('Return a result with a SELECT query.');const rows=[];while(stmt.step()){if(rows.length>=100)throw new Error('Result exceeds 100 rows. Add a filter or LIMIT.');rows.push(stmt.get());}stmt.free();stmt=null;const second=iterator.next();if(!second.done){second.value.free();throw new Error('Run one query at a time.');}self.postMessage({columns,rows});}catch(e){self.postMessage({error:String(e.message||e).slice(0,1000)});}finally{if(stmt)stmt.free();if(db)db.close();}};}
function stopSQL(){if(sqlWorker)sqlWorker.terminate();sqlWorker=null;clearTimeout(sqlTimer);}
function runSQL(){if(sqlWorker)return;const c=D.sql.find(c=>c.id===ui.sql),r=state().sql[c.id]||(state().sql[c.id]={query:c.starter,hint:0,runs:0});if(!r.query.trim()){A.toast('Write a query before running it.');return;}if(!Array.isArray(window.L4_SQL_PARTS)||window.L4_SQL_PARTS.length!==22||!Array.from({length:22},(_,i)=>typeof window.L4_SQL_PARTS[i]==='string').every(Boolean)||typeof Worker==='undefined'){sqlResult={id:c.id,error:'The local SQL engine is unavailable. Keep the complete vendor folder with these files and use a browser supporting Web Workers.'};redraw();return;}const url=URL.createObjectURL(new Blob([window.L4_SQL_PARTS.join(''),'; ('+workerMain.toString()+')();'],{type:'application/javascript'}));try{sqlWorker=new Worker(url);URL.revokeObjectURL(url);const finish=result=>{stopSQL();sqlResult={id:c.id,...result};r.runs++;persist();if(A.view()==='sql'){redraw();document.getElementById('prep-sql-result')?.focus();}A.celebrate(!result.error&&matches(c,result));};sqlWorker.onmessage=e=>finish(e.data);sqlWorker.onerror=e=>{e.preventDefault();finish({error:'The query worker could not finish. Reload the local files and try again.'});};sqlTimer=setTimeout(()=>finish({error:'Stopped after 8 seconds. Simplify the query and check for an unbounded recursive query or large join.'}),8000);sqlWorker.postMessage({setup:D.sqlSetup,query:r.query});redraw();}catch{URL.revokeObjectURL(url);stopSQL();sqlResult={id:c.id,error:'This browser could not start the local SQL worker.'};redraw();}}
function flow(text){return `<div class="prep-diagram prep-flow" aria-label="Visual example">${text.split(/\s*(→|↔|↻|←)\s*/).filter(Boolean).map(t=>`<span class="${/^[→↔↻←]$/.test(t)?'prep-flow-arrow':'prep-flow-part'}">${E(t)}</span>`).join('')}</div>`;}
function compare(){const c=D.comparisons.find(c=>c.id===ui.comparison),r=state().comparisons[c.id]||{variant:0,choice:null,reason:'',revealed:false},q=c.questions[r.variant];return shell('compare','See the difference. Use the idea.','Pair the visual memory cue with a decision in context.',`${select('Comparison','prep-compare-select',Object.fromEntries(D.comparisons.map(c=>[c.id,c.title])),c.id)}<section class="panel"><p>${ksbLinks(c.ksbs)}</p><h2>${c.title}</h2><div class="prep-compare-pair">${[c.left,c.right].map((side,i)=>`<article><span class="prep-side-number" aria-hidden="true">${i+1}</span><h3>${side[0]}</h3><p>${side[1]}</p>${flow(side[2])}</article>`).join('')}</div><form id="prep-compare-form"><h3>Apply the distinction · question ${r.variant+1} of 2</h3><p>${q.text}</p><fieldset><legend>Which fits this situation?</legend>${[c.left,c.right].map((side,i)=>`<label class="choice-option"><input type="radio" name="prep-comparison" value="${i}"${r.choice===i?' checked':''}${r.revealed?' disabled':''} required>${side[0]}</label>`).join('')}</fieldset>${textarea('Why does that choice fit?','prep-compare-reason',r.reason,`required maxlength="2000"${r.revealed?' readonly':''}`)}${!r.revealed?'<button class="button small" type="submit">Check this application</button>':`<div class="note" role="status"><strong>${r.choice===q.answer?'Your choice matches.':'Revisit the distinction.'}</strong><p>${q.why}</p>${button('Try the other situation','compare-next','',true)}</div>`}</form></section>`);}
function terms(){const needle=ui.termSearch.toLowerCase(),terms=D.glossary.filter(t=>(t.term+' '+t.definition+' '+t.ksbs.join(' ')).toLowerCase().includes(needle));return shell('terms','A definition when you need it','Dotted terms in KSB lessons open these short explanations without leaving the lesson.',`${input('Find a term or KSB','prep-term-search',ui.termSearch,'search')}<div id="prep-term-results" class="prep-grid">${terms.map(t=>termCard(t)).join('')||'<p>No terms match. Try a KSB code or a shorter word.</p>'}</div>`);}
function termCard(t){return `<article class="prep-card"><h2>${E(t.term)}</h2><p>${E(t.definition)}</p><div class="prep-diagram">${E(t.visual)}</div><p><strong>Watch out:</strong> ${E(t.mistake)}</p><p class="small">${ksbLinks(t.ksbs)}</p></article>`;}
function openTerm(id,opener){const t=D.glossary.find(t=>t.id===id);if(!t)return;let dialog=document.getElementById('prep-term-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='prep-term-dialog';dialog.setAttribute('aria-labelledby','prep-term-title');document.body.append(dialog);}dialog.innerHTML=`<h2 id="prep-term-title">${E(t.term)}</h2><p>${E(t.definition)}</p><div class="prep-diagram">${E(t.visual)}</div><p><strong>Common mistake:</strong> ${E(t.mistake)}</p><form method="dialog"><button class="button small">Back to my lesson</button></form>`;dialog.onclose=()=>{if(opener?.isConnected)opener.focus();};dialog.showModal();}
function annotateTerms(root){const used=new Set(),ordered=[...D.glossary].sort((a,b)=>b.term.length-a.term.length);root.querySelectorAll('.prose').forEach(prose=>{const walker=document.createTreeWalker(prose,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('a,button,code,pre,textarea,svg,[data-prep-glossary]')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){let value=node.textContent,parts=[],cursor=0;const hits=[];for(const t of ordered){if(used.has(t.id))continue;const re=new RegExp('\\b'+t.term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i'),m=re.exec(value);if(m)hits.push({t,start:m.index,end:m.index+m[0].length,text:m[0]});}hits.sort((a,b)=>a.start-b.start);if(!hits.length)continue;const frag=document.createDocumentFragment();for(const hit of hits){if(hit.start<cursor||used.has(hit.t.id))continue;frag.append(document.createTextNode(value.slice(cursor,hit.start)));const b=document.createElement('button');b.type='button';b.className='prep-term';b.dataset.prep='term';b.dataset.id=hit.t.id;b.setAttribute('aria-label','Explain '+hit.t.term);b.textContent=hit.text;frag.append(b);used.add(hit.t.id);cursor=hit.end;}frag.append(document.createTextNode(value.slice(cursor)));node.replaceWith(frag);}});}
function database(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{try{const req=indexedDB.open('l4-fellowship-audio.v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('clips');req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result);};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('Audio database is blocked.'));}catch(e){reject(e);}}).catch(e=>{dbPromise=null;throw e;});return dbPromise;}
async function clipStore(mode,id,value){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('clips',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('clips'),req=mode==='get'?store.get(id):mode==='delete'?store.delete(id):store.put(value,id);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||new Error('Audio could not be stored.'));tx.onabort=()=>reject(tx.error||new Error('Audio storage was interrupted.'));});}
async function getClip(id){if(memoryAudio.has(id))return memoryAudio.get(id);try{return await clipStore('get',id);}catch{return null;}}
function revokeAudio(){for(const url of audioURLs)URL.revokeObjectURL(url);audioURLs=[];}
function speak(){const s=state(),pending=audio&&audio.status==='asking',running=audio&&audio.status==='recording';return shell('speak','Hear how your answer lands','Record a short explanation, listen back and check what you actually covered.',`<section class="panel"><div class="two-fields">${select('KSB to explain','prep-speak-ksb',ksbs(),ui.speakKsb,audio?'disabled':'')}${select('Maximum recording length','prep-speak-limit',{60:'1 minute',120:'2 minutes'},ui.limit,audio?'disabled':'')}</div><h2>${E(A.byId(ui.speakKsb).question)}</h2><p class="small">Use a sanitised example and your own contribution. Microphone access is requested only after you press Start. Audio stays on this device; there is no upload or transcription.</p><div class="button-row">${button(pending?'Waiting for microphone permission…':running?'Recording…':'Start recording','audio-start',audio?'disabled':'')}${audio?button(pending?'Cancel microphone request':'Stop and keep recording','audio-stop','',true):''}</div><p id="prep-audio-clock" role="timer" aria-label="Recording elapsed time">${running?'Recording · 0 seconds':''}</p><p id="prep-audio-status" role="status">${E(audioMessage)}</p><p class="small muted">Leaving this tool or hiding the tab stops recording. The browser must support microphone capture in a secure context such as HTTPS or localhost.</p></section><section class="content-section"><h2>Your recordings (${Object.keys(s.recordings).length})</h2><p class="note">JSON backups include recording titles and self-reviews, but <strong>not audio files</strong>. Export each audio clip separately before clearing browser data or moving devices.</p>${Object.values(s.recordings).reverse().map(r=>`<article class="panel" data-recording="${r.id}"><h3>${E(r.ksb)} · ${E(r.date)} · ${r.duration} second${r.duration===1?'':'s'}</h3><div data-audio-slot="${r.id}"><p class="small">Checking this device for the audio…</p></div><fieldset class="prep-checks"><legend>After listening: did I explain…?</legend>${checkNames.map((label,n)=>`<label><input type="checkbox" data-audio-check="${r.id}" data-check="${n}"${r.checks[n]?' checked':''}>${label}</label>`).join('')}</fieldset>${textarea('One thing to improve next time','prep-audio-note-'+r.id,r.note,`data-audio-note="${r.id}" maxlength="2000"`)}<div class="button-row">${button('Export audio file','audio-export',`data-id="${r.id}"`,true)}${button('Delete recording','remove',`data-kind="recordings" data-id="${r.id}"`,true)}${ksbLinks([r.ksb])}</div></article>`).join('')||'<div class="quiet-box">Your first recorded answer will appear here with playback and a short self-review.</div>'}</section>`);}
async function mountAudio(){const generation=audioToken;for(const slot of document.querySelectorAll('[data-audio-slot]')){const id=slot.dataset.audioSlot,blob=await getClip(id);if(generation!==audioToken||!slot.isConnected)continue;slot.replaceChildren();if(blob instanceof Blob&&blob.size){const url=URL.createObjectURL(blob);audioURLs.push(url);const player=document.createElement('audio');player.controls=true;player.preload='metadata';player.src=url;player.setAttribute('aria-label','Playback '+state().recordings[id]?.ksb+' answer');slot.append(player);if(memoryAudio.has(id)){const p=document.createElement('p');p.className='error-text';p.textContent='Audio is in temporary memory. Export it before closing this page.';slot.append(p);}}else slot.textContent='The audio file is not on this device. This review may have arrived in a JSON backup; the text below remains available.';}}
async function startAudio(){if(audio)return;if(Object.keys(state().recordings).length>=500){A.toast('Export and delete an older recording before adding another.');return;}if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){audioMessage='Microphone recording is unavailable here. Open the page in a browser that supports recording over HTTPS or localhost. You can still rehearse aloud.';redraw();return;}const capture={id:A.uid(),ksb:ui.speakKsb,limit:ui.limit,status:'asking',chunks:[],cancelled:false};audio=capture;audioMessage='Choose whether to allow microphone access in your browser.';redraw();try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(capture.cancelled||audio!==capture||A.view()!=='speak'||document.hidden){stream.getTracks().forEach(t=>t.stop());return;}capture.stream=stream;const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));capture.recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);capture.recorder.ondataavailable=e=>{if(e.data.size)capture.chunks.push(e.data);};capture.recorder.onerror=()=>{audioMessage='Recording was interrupted. Any captured audio will be kept when possible.';stopAudio();};capture.recorder.onstop=()=>finishAudio(capture);capture.started=Date.now();capture.status='recording';capture.recorder.start(250);capture.timeout=setTimeout(stopAudio,capture.limit*1000);audioMessage='Recording on this device. Stop whenever your explanation is complete.';redraw();}catch(e){if(capture.stream)capture.stream.getTracks().forEach(t=>t.stop());if(audio===capture){audio=null;audioMessage=e.name==='NotAllowedError'?'Microphone access was not granted. You can allow it in browser settings and try again.':'The microphone could not start. Check that it is available and try again.';if(A.view()==='speak')redraw();}}}
function stopAudio(){const capture=audio;if(!capture)return;clearTimeout(capture.timeout);if(capture.status==='asking'){capture.cancelled=true;audio=null;audioMessage='Microphone request cancelled. No recording was started.';if(A.view()==='speak')redraw();return;}if(capture.status==='stopping')return;capture.status='stopping';capture.ended=Date.now();try{if(capture.recorder.state!=='inactive')capture.recorder.stop();}finally{capture.stream.getTracks().forEach(t=>t.stop());}}
async function finishAudio(capture){clearTimeout(capture.timeout);capture.stream?.getTracks().forEach(t=>t.stop());const mime=capture.recorder.mimeType||capture.chunks[0]?.type||'audio/webm',blob=new Blob(capture.chunks,{type:mime});if(blob.size&&/^audio\/(webm|ogg|mp4)(;codecs=[a-zA-Z0-9.,-]+)?$/.test(mime)){memoryAudio.set(capture.id,blob);let stored=false;if(A.writable())try{await clipStore('put',capture.id,blob);stored=true;}catch{}state().recordings[capture.id]={id:capture.id,ksb:capture.ksb,date:A.today(),duration:Math.min(121,Math.max(1,Math.round(((capture.ended||Date.now())-capture.started)/1000))),mime,checks:emptyChecks(),note:''};persist();if(stored&&A.writable()){memoryAudio.delete(capture.id);audioMessage='Recording saved on this device. Listen back, then add your self-review.';}else audioMessage='Audio could not be saved persistently. Export this clip now; it is available in temporary memory.';}else audioMessage='No usable audio was captured. Check the microphone and try another short answer.';if(audio===capture)audio=null;if(A.view()==='speak')redraw();else A.toast(audioMessage);}
function blobDownload(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function ticks(){const m=state().activeMock,el=document.getElementById('prep-mock-time');if(m&&el){const seconds=Math.max(0,Math.floor((Date.now()-m.started)/1000));el.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')} elapsed${seconds>=m.minutes*60?' · suggested time reached':''}`;}const clock=document.getElementById('prep-audio-clock');if(audio?.status==='recording'&&clock)clock.textContent=`Recording · ${Math.min(audio.limit,Math.floor((Date.now()-audio.started)/1000))} / ${audio.limit} seconds`;}
function summary(s){const lines=['','## Preparation studio','Practice and self-review records; no automatic assessment grade.','Audio files are exported separately; this summary contains self-reviews only.',''];if(s.activeMock)lines.push('### Unfinished mock',...s.activeMock.queue.map((id,i)=>`${id}: ${s.activeMock.answers[i].response}`),'');for(const m of Object.values(s.mocks))lines.push('### Mock '+m.finished,...m.queue.flatMap((id,i)=>[id+': '+m.answers[i].response,'Self-checks: '+checkNames.filter((_,n)=>m.answers[i].checks[n]).join('; '),'Next: '+m.answers[i].next]),'');for(const m of Object.values(s.mistakes))lines.push('### Learning point '+m.ksb,'Source: '+m.source,'What I thought: '+m.thought,'Why: '+m.why,'Remember: '+m.remember,'Revisit: '+m.nextReview,'Latest explanation: '+m.response,'');for(const r of Object.values(s.resources))lines.push('### Resource '+r.title,r.ksbs.join(', '),r.url,r.notes,'');for(const [id,r] of Object.entries(s.sql))lines.push('### SQL draft '+id,r.query,'Runs: '+r.runs,'');for(const [id,r] of Object.entries(s.comparisons))lines.push('### Comparison '+id,'Situation '+(r.variant+1)+'; choice '+(r.choice===null?'unset':r.choice+1),r.reason,'');for(const r of Object.values(s.recordings))lines.push('### Spoken answer '+r.ksb+' '+r.date,r.duration+' seconds; audio exported separately.','Self-checks: '+checkNames.filter((_,n)=>r.checks[n]).join('; '),r.note,'');if(s.mistakeDraft)lines.push('### Unfinished mistake entry',JSON.stringify(s.mistakeDraft),'');if(s.resourceDraft)lines.push('### Unfinished resource',JSON.stringify(s.resourceDraft),'');return lines;}
function captureInput(el){const s=state(),id=el.id;let changed=true;
 if(id==='prep-mock-response'&&s.activeMock)s.activeMock.answers[s.activeMock.index].response=el.value;
 else if(el.dataset.mockNext&&s.mocks[el.dataset.mockNext])s.mocks[el.dataset.mockNext].answers[Number(el.dataset.index)].next=el.value;
 else if(el.dataset.mockCheck&&s.mocks[el.dataset.mockCheck])s.mocks[el.dataset.mockCheck].answers[Number(el.dataset.index)].checks[Number(el.dataset.check)]=el.checked;
 else if(id.startsWith('prep-mistake-')&&s.mistakeDraft&&['ksb','source','thought','why','remember','date'].includes(id.slice(13))){const field=id.slice(13);s.mistakeDraft[field==='date'?'nextReview':field]=el.value;}
 else if(el.dataset.mistakeResponse&&s.mistakes[el.dataset.mistakeResponse])s.mistakes[el.dataset.mistakeResponse].response=el.value;
 else if(id.startsWith('prep-resource-')&&s.resourceDraft&&['title','url','notes'].includes(id.slice(14)))s.resourceDraft[id.slice(14)]=el.value;
 else if(el.dataset.resourceKsb&&s.resourceDraft)s.resourceDraft.ksbs=Array.from(document.querySelectorAll('[data-resource-ksb]:checked')).map(e=>e.dataset.resourceKsb);
 else if(id==='prep-sql-query'){const c=D.sql.find(c=>c.id===ui.sql),r=s.sql[c.id]||(s.sql[c.id]={query:c.starter,hint:0,runs:0});r.query=el.value;}
 else if(id==='prep-compare-reason'||el.name==='prep-comparison'){const r=s.comparisons[ui.comparison]||(s.comparisons[ui.comparison]={variant:0,choice:null,reason:'',revealed:false});if(!r.revealed){if(id==='prep-compare-reason')r.reason=el.value;else r.choice=Number(el.value);}}
 else if(el.dataset.audioCheck&&s.recordings[el.dataset.audioCheck])s.recordings[el.dataset.audioCheck].checks[Number(el.dataset.check)]=el.checked;
 else if(el.dataset.audioNote&&s.recordings[el.dataset.audioNote])s.recordings[el.dataset.audioNote].note=el.value;
 else changed=false;
 if(changed)A.saveSoon();return changed;
}
async function click(action,b){const s=state(),id=b.dataset.id;
 if(action==='term'){openTerm(id,b);return;}
 if(action==='mock-start'){if(!room('mocks'))return;const count=Number(document.getElementById('prep-mock-count').value),n=Object.keys(s.mocks).length,queue=[];for(let repeat=0;repeat<count/3;repeat++)for(const category of ['K','S','B']){const ids=A.items.filter(k=>k.id[0]===category).map(k=>k.id);queue.push(ids[(n+repeat)%ids.length]);}s.activeMock={id:A.uid(),date:A.today(),started:Date.now(),minutes:count===3?10:20,index:0,queue,answers:queue.map(()=>({response:'',checks:emptyChecks(),next:''})),finished:''};persist();redraw();return;}
 if(action==='mock-next'&&s.activeMock){const m=s.activeMock;if(!m.answers[m.index].response.trim()&&!confirm('Leave this answer blank and continue? The review will show the gap.'))return;if(m.index<m.queue.length-1)m.index++;else{m.finished=A.today();s.mocks[m.id]=m;ui.mock=m.id;s.activeMock=null;}persist();redraw();return;}
 if(action==='mock-prev'&&s.activeMock){s.activeMock.index=Math.max(0,s.activeMock.index-1);persist();redraw();return;}
 if(action==='mock-open'){ui.mock=id;if(s.activeMock){A.toast('Your current mock is paused. Finish it before opening model-answer reviews.');return;}redraw();return;}
 if(action==='mock-export'){const subset=blank();subset.mocks[id]=s.mocks[id];A.download('l4-mock-'+s.mocks[id].date+'.md',summary(subset).join('\n'),'text/markdown');return;}
 if(action==='mistake-new'){s.mistakeDraft=newMistake();persist();redraw();return;}
 if(action==='quiz-mistake'){const q=A.quiz().find(q=>q.id===id),session=A.state().learningTools.quizSession;if(!q)return;if(s.mistakeDraft&&!confirm('Replace the unfinished notebook draft? Saved notebook entries will remain.'))return;s.mistakeDraft=newMistake(q.ksbs[0],q.id+' · '+q.statement,session?.reason||'');persist();A.go('mistakes');return;}
 if(action==='mistake-edit'){if(s.mistakeDraft&&s.mistakeDraft.id!==id&&!confirm('Replace the unfinished notebook draft?'))return;s.mistakeDraft=structuredClone(s.mistakes[id]);persist();redraw();return;}
 if(action==='mistake-cancel'){if(!confirm('Discard this unfinished notebook draft?'))return;s.mistakeDraft=null;persist();redraw();return;}
 if(action==='mistake-review'){const m=s.mistakes[id];if(!m.response.trim()){A.toast('Write a short explanation before recording your revisit.');return;}m.reviewedDate=A.today();m.nextReview=A.addDays(Number(b.dataset.days));persist();redraw();return;}
 if(action==='mistake-variant'){const m=s.mistakes[id];if(m.response.trim()&&!confirm('Switch questions and clear this revisit response? The saved correction stays.'))return;m.variant=1-m.variant;m.response='';persist();redraw();return;}
 if(action==='resource-new'||action==='resource-topic'){if(action==='resource-topic')ui.materialFilter=id;if(s.resourceDraft&&action==='resource-topic'){A.toast('Your unfinished resource is ready to continue.');A.go('materials');return;}s.resourceDraft=resourceDraft();persist();if(A.view()==='materials')redraw();else A.go('materials');return;}
 if(action==='resource-edit'){if(s.resourceDraft&&s.resourceDraft.id!==id&&!confirm('Replace the unfinished resource draft?'))return;s.resourceDraft=structuredClone(s.resources[id]);persist();redraw();return;}
 if(action==='resource-cancel'){if(!confirm('Discard this unfinished resource draft?'))return;s.resourceDraft=null;persist();redraw();return;}
 if(action==='sql-run'){runSQL();return;}
 if(action==='sql-hint'||action==='sql-reset'){const c=D.sql.find(c=>c.id===ui.sql),r=s.sql[c.id]||(s.sql[c.id]={query:c.starter,hint:0,runs:0});if(action==='sql-hint')r.hint=Math.min(3,r.hint+1);else{if(!confirm('Reset this query to its starter?'))return;r.query=c.starter;r.hint=0;sqlResult=null;stopSQL();}persist();redraw();return;}
 if(action==='compare-next'){const r=s.comparisons[ui.comparison];r.variant=1-r.variant;r.choice=null;r.reason='';r.revealed=false;persist();redraw();return;}
 if(action==='speak-topic'){ui.speakKsb=id;A.go('speak');return;}
 if(action==='audio-start'){await startAudio();return;}
 if(action==='audio-stop'){stopAudio();return;}
 if(action==='audio-export'){const blob=await getClip(id);if(!blob){A.toast('This audio file is not available on this device. JSON backups contain its review only.');return;}const r=s.recordings[id],extension=r.mime.includes('mp4')?'m4a':r.mime.includes('ogg')?'ogg':'webm';blobDownload('l4-'+r.ksb+'-'+r.date+'-'+id.slice(-6)+'.'+extension,blob);return;}
 if(action==='remove'){if(s.deleted.length>=3000){A.toast('The removal history is full. Export your records before resetting this browser’s site data.');return;}const kind=b.dataset.kind;if(!['mocks','mistakes','resources','recordings'].includes(kind)||!s[kind][id])return;if(!confirm('Delete this '+({mocks:'mock review',mistakes:'notebook entry',resources:'resource',recordings:'recording and self-review'}[kind])+'? Export a copy first if you want to keep it.'))return;delete s[kind][id];s.deleted.push(kind+':'+id);if(kind==='mistakes'&&s.mistakeDraft?.id===id)s.mistakeDraft=null;if(kind==='resources'&&s.resourceDraft?.id===id)s.resourceDraft=null;persist();if(kind==='recordings'){memoryAudio.delete(id);try{await clipStore('delete',id);}catch{A.toast('The recording reference was removed. Browser audio storage could not be cleared; use browser site-data controls if needed.');}}redraw();}
}
function submit(event){const s=state(),id=event.target.id;if(!id.startsWith('prep-'))return;event.preventDefault();
 if(id==='prep-mistake-form'){const d=s.mistakeDraft;if(d&&!room('mistakes',d.id))return;if(!d||![d.thought,d.why,d.remember].every(v=>v.trim())){A.toast('Complete all three reflections before saving.');return;}s.mistakes[d.id]=structuredClone(d);s.mistakeDraft=null;persist();redraw();A.toast(A.writable()?'Notebook entry saved.':'Notebook entry is in temporary memory. Export a backup.');}
 if(id==='prep-resource-form'){const d=s.resourceDraft;if(d&&!room('resources',d.id))return;if(!d)return;if(!d.title.trim()||!d.ksbs.length||(!d.notes.trim()&&!d.url)||d.url&&!safeUrl(d.url)){document.getElementById('prep-resource-error').textContent='Add a title, at least one KSB and either notes or a valid http/https link without embedded credentials.';return;}if(d.url)d.url=safeUrl(d.url);s.resources[d.id]=structuredClone(d);s.resourceDraft=null;persist();redraw();A.toast(A.writable()?'Resource saved beside its KSB lessons.':'Resource is in temporary memory. Export a backup.');}
 if(id==='prep-compare-form'){const r=s.comparisons[ui.comparison];if(!r||r.choice===null||!r.reason.trim()||r.revealed)return;r.revealed=true;persist();redraw();A.celebrate(r.choice===D.comparisons.find(c=>c.id===ui.comparison).questions[r.variant].answer);}
}
function init(api){A=api;document.addEventListener('click',event=>{const b=event.target.closest('[data-prep]');if(b)click(b.dataset.prep,b).catch(()=>A.toast('That action could not finish. Your existing records are retained.'));});document.addEventListener('input',event=>{const el=event.target;captureInput(el);if(el.id==='prep-term-search'){ui.termSearch=el.value;const needle=ui.termSearch.toLowerCase();document.getElementById('prep-term-results').innerHTML=D.glossary.filter(t=>(t.term+' '+t.definition+' '+t.ksbs.join(' ')).toLowerCase().includes(needle)).map(termCard).join('')||'<p>No terms match.</p>';}});document.addEventListener('change',event=>{const el=event.target;captureInput(el);const map={'prep-sql-select':'sql','prep-compare-select':'comparison','prep-resource-filter':'materialFilter','prep-mistake-filter':'mistakeFilter','prep-speak-ksb':'speakKsb','prep-speak-limit':'limit'};if(el.id==='prep-route'){A.go(el.value);return;}if(map[el.id]){ui[map[el.id]]=el.id==='prep-speak-limit'?Number(el.value):el.value;if(el.id==='prep-sql-select'){stopSQL();sqlResult=null;}redraw();}});document.addEventListener('submit',submit);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio();});window.addEventListener('pagehide',()=>{stopAudio();stopSQL();revokeAudio();});window.addEventListener('beforeunload',event=>{if(audio?.status==='recording'||audio?.status==='stopping'||memoryAudio.size){event.preventDefault();event.returnValue='';}});setInterval(ticks,1000);}
function beforeRender(view){if(view!=='speak'&&audio)stopAudio();if(view!=='sql')stopSQL();audioToken++;revokeAudio();}
function mount(view,root){if(view==='speak')mountAudio();if(view==='lesson')annotateTerms(root);ticks();}
function render(view){return ({prep:studio,mock,mistakes,sql,compare,speak,materials,terms})[view]();}
window.L4_PREP={setSpokenKsb:id=>{if(A.items.some(k=>k.id===id))ui.speakKsb=id;},spokenKsb:()=>ui.speakKsb,routes,names,blank,validate,merge,init,beforeRender,mount,render,lessonPanel,summary};
})();
